def _m(group, title, subtitle, unit, color, what, read, why):
    return meta(CATEGORY, group, title, subtitle, unit, color, what=what, read=read, why=why)

def _s(key, group, labels, values, source, unit, note, title, subtitle, color, what, read, why, chart=None):
    return single(key, labels, values, source=source, unit=unit, note=note,
                  meta_=_m(group,title,subtitle,unit,color,what,read,why), chart=chart)

def _d(key, group, labels, datasets, source, unit, note, title, subtitle, color, what, read, why, chart=None):
    return multi(key, labels, datasets, source=source, unit=unit, note=note,
                 meta_=_m(group,title,subtitle,unit,color,what,read,why), chart=chart)

